Vue.component("loader",{template:"#loader-tpl",data:function data(){return{defaultZIndex:9999,loaderVisible:!1,zIndex:-1,bgColor:"rgba(0, 0, 0, 0.3)"}},methods:{showLoader:function showLoader(){this.loaderVisible=!0},hideLoader:function hideLoader(){this.loaderVisible=!1}},beforeCreate:function beforeCreate(){var self=this;window.APTS.vueEventBus.$on("showGlobalLoader",(function(zIndex){self.zIndex=zIndex||self.defaultZIndex,self.showLoader()})),window.APTS.vueEventBus.$on("hideGlobalLoader",(function(){self.hideLoader()}))}});